import numpy as np

# Let's write a robust scoring script and compare column by column with pipeline_output.csv
raw = pd.read_csv('raw_responses.csv')
pipe = pd.read_csv('pipeline_output.csv')

def score_phq9(df):
    totals = []
    bands = []
    prorateds = []
    flags = []

    for idx, row in df.iterrows():
        items = [row[f'phq9_{i}'] for i in range(1, 10)]
        # Check invalid or missing
        valid_items = []
        missing_count = 0
        for val in items:
            if pd.isna(val) or val not in [0, 1, 2, 3]:
                missing_count += 1
            else:
                valid_items.append(val)

        # Self-harm flag based on q9
        q9 = row['phq9_9']
        if pd.isna(q9) or q9 not in [0, 1, 2, 3]:
            flag = None
        else:
            flag = (q9 > 0)
        flags.append(flag)

        if missing_count >= 2:
            totals.append(np.nan)
            bands.append(np.nan)
            prorateds.append(np.nan)
        elif missing_count == 1:
            # sum of 8 items, multiply by 9, divide by 8
            s = sum(valid_items)
            raw_score = (s * 9) / 8.0
            # Round: halves always round up (e.g. 4.5 -> 5, 10.5 -> 11)
            # In Python, round(x + 1e-9) or Decimal ROUND_HALF_UP
            from decimal import Decimal, ROUND_HALF_UP
            total = int(Decimal(str(raw_score)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            totals.append(total)
            prorateds.append(True)
            bands.append(get_phq9_band(total))
        else:
            total = sum(items)
            totals.append(total)
            prorateds.append(False)
            bands.append(get_phq9_band(total))

    return pd.DataFrame({
        'phq9_total': totals,
        'phq9_band': bands,
        'phq9_prorated': prorateds,
        'phq9_self_harm_flag': flags
    })

def get_phq9_band(total):
    if pd.isna(total):
        return np.nan
    if total <= 4:
        return 'none-minimal'
    elif total <= 9:
        return 'mild'
    elif total <= 14:
        return 'moderate'
    elif total <= 19:
        return 'moderately severe'
    else:
        return 'severe'

